Method.Source:
/// <summary>
/// send report as byte array.
/// </summary>
/// <param name = "str">The configuration.</param>
/// <param name = "ParameterValue">parameter value.</param>
/// <param name = "SRSReportFileFormat">file format.</param>
/// <param name = "string">Device info.</param>
/// <param name = "string">execution id.</param>
/// <returns>A <c>Byte</c> object.</returns>
public System.Byte[] renderReportToByteArray(str                _reportPath,
                                             Microsoft.Dynamics.AX.Framework.Reporting.Shared.ReportingService.ParameterValue[] _parameterValueArray,
                                             SRSReportFileFormat _fileFormat,
                                             str                 _deviceInfo,
                                             str                 _executionID)
{
    System.Byte[]  reportBytes = next renderReportToByteArray(_reportPath,_parameterValueArray,_fileFormat,_deviceInfo,_executionID);


    if(isConfigurationkeyEnabled(configurationKeyNum(AVADAI)))
    {

        System.Byte[] archiveByte = reportBytes;

        if (!this.AVADAIparmCalledArchive() && this.AVADAIisArchiveReport(_reportPath) && this.AVADAIparmCalledRVRefreshComplete())
        {
            this.AVADAIprintToArchive(_reportPath, _parameterValueArray, SRSReportFileFormat::PDF, _deviceInfo,archiveByte);
        }
    }
    return reportBytes;
}

/// <summary>
/// send report to printer.
/// </summary>
/// <param name = "string">report path</param>
/// <param name = "ParameterValue">parameter value.</param>
/// <param name = "string">printer name.</param>
/// <param name = "boolean">printer settings boolean value.</param>
/// <param name = "string">Device info.</param>
/// <param name = "integer">Number of copies.</param>
/// <param name = "boolean">Override paper setting </param>
/// <param name = "string">Page setting.</param>
/// <returns>A <c>Byte</c> object.</returns>
public boolean renderReportToPrinter(str        _reportPath,
                                     Microsoft.Dynamics.AX.Framework.Reporting.Shared.ReportingService.ParameterValue[] _parameterValueArray,
                                     str        _printerName,
                                     boolean    _overridePrintContractSettings,
                                     str        _deviceInfo,
                                     int        _numberOfCopies,
                                     boolean    _overridePaperSettings,
                                     str        _pageSettings)
{
    boolean success = next renderReportToPrinter(_reportPath,_parameterValueArray,_printerName,_overridePrintContractSettings,_deviceInfo,_numberOfCopies,_overridePaperSettings,_pageSettings);

    if(isConfigurationkeyEnabled(configurationKeyNum(AVADAI)))
    {

        if (!this.AVADAIparmCalledArchive() && this.AVADAIisArchiveReport(_reportPath))
        {
            setPrefix("@AVADAI:AVADAIShort");

            this.AVADAIprintToArchive(_reportPath, _parameterValueArray, SRSReportFileFormat::PDF, _deviceInfo,Null);
        }
    }
    return success;
}
